import { NavLink } from "react-router-dom"
export default function MainNavigation(){
    return(
        <header>
            <nav>
                <ul>
                    <li><Nav to="/">Home</Nav></li>
                    <li><Link to="/products">Products</Link></li>
                </ul>
            </nav>
        </header>
    )
}
